// One camera track; opaque scene planes separated by a textured foreground wall.
export const passageDefaults={historyPassageDirection:'right',historyPassageStart:17.2,historyPassageEnd:20.0,historyPassageWallWidth:520,historyPassageDepth:55,historyPassageWallLight:.85,historyPassageSoftness:80};
const clamp=x=>Math.max(0,Math.min(1,x));
export function passageState(age,input={}){const f={...passageDefaults,...input},start=Number(f.historyPassageStart),end=Math.max(start+.2,Number(f.historyPassageEnd)),u=clamp((age-start)/(end-start)),p=u*u*u*(u*(u*6-15)+10),width=Math.max(80,Number(f.historyPassageWallWidth)||520),axis=['up','down'].includes(f.historyPassageDirection)?'y':'x',sign=['left','up'].includes(f.historyPassageDirection)?-1:1,extent=axis==='y'?540:960,travel=extent+width,outgoing=travel*p+Math.max(0,Math.min(180,f.historyPassageDepth))*p*(1-p),incoming=travel*(p-1);return {start,end,u,p,outgoing,incoming,axis,sign,extent,wallLeft:incoming+extent,wallRight:outgoing,active:age>=start&&age<end};}
let wall;
function wallTexture(){if(wall)return wall;wall=Object.assign(document.createElement('canvas'),{width:320,height:540});const c=wall.getContext('2d'),im=c.createImageData(320,540);for(let y=0;y<540;y++)for(let x=0;x<320;x++){const n=Math.sin(x*12.9898+y*78.233)*43758.5453,grain=(n-Math.floor(n))-.5,light=18+5*Math.sin(x*.017+y*.006)+3*Math.cos(y*.025)+grain*4,i=(y*320+x)*4;im.data[i]=light;im.data[i+1]=light+1;im.data[i+2]=light+2;im.data[i+3]=255;}c.putImageData(im,0,0);return wall;}
export function paintSpatialPassage(c,age,input,paintOutgoing,paintIncoming){const f={...passageDefaults,...input},s=passageState(age,f),vertical=s.axis==='y';c.save();c.fillStyle='#131516';c.fillRect(0,0,960,540);c.restore();const rect=(at,width)=>vertical?[0,at,960,width]:[at,0,width,540],plane=(at,draw)=>{c.save();c.beginPath();c.rect(...rect(at,s.extent));c.clip();c.translate(vertical?0:at,vertical?at:0);draw();c.restore();};plane(s.incoming*s.sign,paintIncoming);plane(s.outgoing*s.sign,paintOutgoing);const lo=s.sign>0?s.wallLeft:-s.outgoing+s.extent,hi=s.sign>0?s.wallRight:-s.incoming,w=Math.max(0,hi-lo);if(w>0){c.save();c.beginPath();c.rect(...rect(lo,w));c.clip();c.filter=`brightness(${Math.max(.1,f.historyPassageWallLight)})`;const im=wallTexture();if(vertical){for(let k=0;k<Math.ceil(w/540);k++)for(let j=0;j<3;j++)c.drawImage(im,j*320,lo+k*540);}else for(let k=0;k<Math.ceil(w/320);k++)c.drawImage(im,lo+k*320,0);c.restore();}const edge=Math.max(0,Math.min(100,f.historyPassageSoftness));if(edge>0){c.save();for(const [at,flip]of [[lo,-1],[hi,1]]){const left=flip<0?at-edge:at,g=vertical?c.createLinearGradient(0,left,0,left+edge):c.createLinearGradient(left,0,left+edge,0);g.addColorStop(0,flip<0?'#080a0c00':'#080a0cee');g.addColorStop(1,flip<0?'#080a0cee':'#080a0c00');c.fillStyle=g;c.fillRect(...rect(left,edge));}c.restore();}return s;}
